import pandas as pd
import json, sys

df = pd.read_excel(sys.argv[1], sheet_name=None)

result = {}
for sheet_name, sheet_df in df.items():
    sheet_df = sheet_df.fillna('')
    columns = sheet_df.columns.tolist()
    row_count = len(sheet_df)

    rows = []
    for _, row in sheet_df.iterrows():
        rows.append([str(v) if pd.notna(v) else '' for v in row.values])

    result[sheet_name] = {
        "columns": columns,
        "row_count": row_count,
        "rows": rows
    }

with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

print(f"Sheets: {len(result)}")
for name, data in result.items():
    print(f"  {name}: {data['row_count']} rows, columns: {data['columns']}")
    for i, row in enumerate(data['rows'][:30]):
        print(f"    Row {i}: {row}")

import xlrd
import json, sys

wb = xlrd.open_workbook(sys.argv[1])

result = {"sheets": [], "total_sheets": wb.nsheets}

for idx in range(wb.nsheets):
    sh = wb.sheet_by_index(idx)
    sheet_info = {
        "name": sh.name,
        "rows": sh.nrows,
        "cols": sh.ncols,
        "merged_cells": [],
        "non_empty_cells": []
    }

    # Get merged cells
    for mc in sh.merged_cells:
        sheet_info["merged_cells"].append({
            "rlo": mc[0], "rhi": mc[1],
            "clo": mc[2], "chi": mc[3],
            "value": str(sh.cell_value(mc[0], mc[2]))
        })

    # Get all non-empty cells
    for r in range(sh.nrows):
        for c in range(sh.ncols):
            val = sh.cell_value(r, c)
            if val != '' and val is not None:
                sheet_info["non_empty_cells"].append({
                    "row": r, "col": c,
                    "value": str(val)
                })

    result["sheets"].append(sheet_info)

with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

for s in result["sheets"]:
    print(f"Sheet: {s['name']} ({s['rows']}x{s['cols']}), merged: {len(s['merged_cells'])}, non-empty: {len(s['non_empty_cells'])}")
    for cell in s["non_empty_cells"][:20]:
        print(f"  [{cell['row']},{cell['col']}]: {cell['value'][:200]}")

